/**
 * Site Worker: serves the static export and adds:
 *  - /api/search — semantic search over the library using Workers AI
 *    (@cf/baai/bge-m3, multilingual so Tamil and English captions both
 *    embed meaningfully).
 *  - /api/ask — the AI twin. RAG over the same search index + a compact
 *    persona fact base (public/persona.json), answered by a small free-tier
 *    chat model, with per-IP + global rate limiting.
 *
 * Document vectors are computed lazily on first use from the build's
 * /search-index.json, then cached in the Cache API keyed by the index
 * content hash — they recompute automatically whenever the library changes.
 */

import { handleAuth } from './auth.mjs'

const MODEL = '@cf/baai/bge-m3'
const TOP_K = 12
const EMBED_BATCH = 90

// @cf/meta/llama-3.1-8b-instruct (the model this project would have reached
// for by default) was deprecated by Cloudflare on 2026-05-30. glm-4.7-flash
// is Cloudflare's own recommended replacement: still on the free Workers AI
// tier, cheaper per token (5,500 / 36,400 neurons per M in/out tokens), and
// multilingual — useful for the occasional Tamil phrase in the twin's voice.
const ASK_MODEL = '@cf/zai-org/glm-4.7-flash'
// Non-reasoning last resort: it has no thinking pass to get lost in, so it
// always returns visible text as long as Workers AI is up at all.
const ASK_FALLBACK_MODEL = '@cf/meta/llama-3.3-70b-instruct-fp8-fast'
const ASK_MAX_QUESTION_LEN = 300
// Reasoning model: thinking tokens count against the budget, so leave enough
// headroom that the visible answer never comes back empty.
const ASK_MAX_TOKENS = 1400
const ASK_TOP_K = 5
const ASK_MIN_SCORE = 0.35
// Free Workers AI tier is 10,000 neurons/day account-wide (shared with
// /api/search embeddings). At ~30 neurons/question this cap leaves headroom.
const ASK_PER_IP_HOURLY_LIMIT = 10
const ASK_GLOBAL_DAILY_LIMIT = 300

const SYSTEM_PROMPT = `You are the AI twin of Nathamuni, speaking directly on his website.

Voice: direct, engineer's clarity, zero guru-speak, tested-on-myself-first, one light Tamil warmth phrase at most. No motivational clichés, no bullet-point essays unless the question genuinely calls for steps.

You may ONLY use the facts in the CONTEXT block below. If someone asks about Nathamuni and the answer isn't in that context, say plainly that you only speak from what he has published, and suggest they ask him directly on Instagram. NEVER invent biographical details, dates, numbers, or events that aren't in the context.

Refuse — briefly and without judgment — any question about: salary or money specifics, relationship status, family details, health history beyond the published back-injury story, phone number, email, address, or anything else private. Point them to Instagram for anything personal.

For general questions about life, discipline, habits, training, or AI that aren't specifically about Nathamuni's biography, answer the way he would: practical, systems-first, concrete and testable, referencing his own tested experience from the context where it's genuinely relevant. Keep answers short — a few sentences to a short paragraph.`

let memoryCache = null // { hash, vectors, items } per isolate
let personaCache = null // persona.json contents, static for the isolate's life
const ipHourlyMemory = new Map() // ip -> { count, resetAt } — fast, best-effort, per isolate

async function sha256(text) {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('')
}

function cosine(a, b) {
  let dot = 0
  let na = 0
  let nb = 0
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i]
    na += a[i] * a[i]
    nb += b[i] * b[i]
  }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) || 1)
}

async function embedTexts(env, texts) {
  const vectors = []
  for (let i = 0; i < texts.length; i += EMBED_BATCH) {
    const batch = texts.slice(i, i + EMBED_BATCH)
    const res = await env.AI.run(MODEL, { text: batch })
    vectors.push(...res.data)
  }
  return vectors
}

async function getIndex(env, request) {
  const indexRes = await env.ASSETS.fetch(new URL('/search-index.json', request.url))
  if (!indexRes.ok) throw new Error('search index missing from build')
  const indexText = await indexRes.text()
  const hash = await sha256(indexText)

  if (memoryCache?.hash === hash) return memoryCache

  const cacheKey = new Request(`https://cache.internal/search-vectors/${hash}`)
  const cache = caches.default
  const cached = await cache.match(cacheKey)
  const items = JSON.parse(indexText)

  if (cached) {
    const vectors = await cached.json()
    memoryCache = { hash, vectors, items }
    return memoryCache
  }

  const texts = items.map((it) =>
    [it.title, it.category, it.tags.join(' '), it.text].filter(Boolean).join('\n')
  )
  const vectors = await embedTexts(env, texts)
  await cache.put(
    cacheKey,
    new Response(JSON.stringify(vectors), {
      headers: { 'content-type': 'application/json', 'cache-control': 'max-age=604800' },
    })
  )
  memoryCache = { hash, vectors, items }
  return memoryCache
}

async function getPersona(env, request) {
  if (personaCache) return personaCache
  const res = await env.ASSETS.fetch(new URL('/persona.json', request.url))
  if (!res.ok) throw new Error('persona.json missing from build')
  personaCache = await res.json()
  return personaCache
}

function buildAskContext(persona, relatedItems) {
  const facts = persona.facts.map((f) => `- ${f}`).join('\n')
  const voice = persona.voice
    .slice(0, 5)
    .map((v) => `- ${v}`)
    .join('\n')
  const related = relatedItems.length
    ? relatedItems.map((it) => `- [${it.category}] "${it.title}": ${it.text}`).join('\n')
    : '(nothing specifically relevant in the video library for this question)'
  return `PUBLISHED FACTS ABOUT NATHAMUNI:\n${facts}\n\nVOICE SAMPLES (match this tone, don't just quote it):\n${voice}\n\nRELEVANT LIBRARY ENTRIES FOR THIS QUESTION:\n${related}`
}

function hourBucket(date = new Date()) {
  return `${date.getUTCFullYear()}${String(date.getUTCMonth() + 1).padStart(2, '0')}${String(date.getUTCDate()).padStart(2, '0')}${String(date.getUTCHours()).padStart(2, '0')}`
}

function dayBucket(date = new Date()) {
  return `${date.getUTCFullYear()}${String(date.getUTCMonth() + 1).padStart(2, '0')}${String(date.getUTCDate()).padStart(2, '0')}`
}

async function readCounter(cache, key) {
  const res = await cache.match(key)
  if (!res) return 0
  const data = await res.json().catch(() => null)
  return data?.count ?? 0
}

async function writeCounter(cache, key, count, maxAgeSeconds) {
  await cache.put(
    key,
    new Response(JSON.stringify({ count }), {
      headers: { 'content-type': 'application/json', 'cache-control': `max-age=${maxAgeSeconds}` },
    })
  )
}

/**
 * Best-effort quota guard: a fast in-memory Map per isolate for the common
 * case (a warm isolate serving repeat requests from the same IP), backed by
 * the Cache API for a rougher cross-isolate approximation. Neither is exact
 * — the Cache API is scoped per data center and reads/increments aren't
 * atomic — but for a "the twin is resting" soft cap this is enough, and
 * matches the pattern /api/search already uses for its vector cache.
 */
async function checkAndBumpRateLimit(env, request) {
  const ip = request.headers.get('CF-Connecting-IP') || 'unknown'
  const now = Date.now()

  const mem = ipHourlyMemory.get(ip)
  if (mem && mem.resetAt > now && mem.count >= ASK_PER_IP_HOURLY_LIMIT) {
    return { allowed: false, reason: 'ip' }
  }

  const cache = caches.default
  const hourKey = new Request(`https://cache.internal/ask-rate/ip/${ip}/${hourBucket()}`)
  const dayKey = new Request(`https://cache.internal/ask-rate/global/${dayBucket()}`)

  const [ipCount, globalCount] = await Promise.all([readCounter(cache, hourKey), readCounter(cache, dayKey)])

  if (globalCount >= ASK_GLOBAL_DAILY_LIMIT) return { allowed: false, reason: 'global' }
  if (ipCount >= ASK_PER_IP_HOURLY_LIMIT) return { allowed: false, reason: 'ip' }

  await Promise.all([
    writeCounter(cache, hourKey, ipCount + 1, 3600),
    writeCounter(cache, dayKey, globalCount + 1, 90000),
  ])

  if (!mem || mem.resetAt <= now) {
    ipHourlyMemory.set(ip, { count: 1, resetAt: now + 3600_000 })
  } else {
    mem.count += 1
  }
  // Guard against unbounded growth in a long-lived isolate under abuse.
  if (ipHourlyMemory.size > 5000) ipHourlyMemory.clear()

  return { allowed: true }
}

/**
 * Anonymous question log — the owner's future content pipeline. Stores only
 * the question text, outcome, and timestamp in KV (no IP, no identity).
 * Inert until an INBOX KV namespace is bound; failures never affect answers.
 */
async function logQuestion(env, question, outcome) {
  if (!env.INBOX) return
  try {
    const key = `q:${Date.now()}:${Math.random().toString(36).slice(2, 8)}`
    await env.INBOX.put(key, JSON.stringify({ question, outcome, at: new Date().toISOString() }))
  } catch (err) {
    console.warn('question log skipped:', err.message)
  }
}

const JOIN_MAX_AMBITION_LEN = 200
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/

/**
 * "Join the lab" capture: email + optional ambition ("what are you chasing").
 * Privacy-honest: stored solely for the weekly newsletter; honeypot-guarded;
 * per-IP rate limited; inert (friendly 503) until the INBOX KV is bound.
 */
/**
 * Sends the double opt-in confirmation via Resend's REST API.
 *
 * Plain fetch, no SDK — the Worker bundle stays dependency-free. Returns false rather
 * than throwing so a mail outage never costs the visitor their signup; the address is
 * already stored by the time this runs.
 *
 * Needs two secrets: RESEND_API_KEY, and JOIN_FROM_EMAIL (an address on a domain
 * verified in Resend). Without them the caller stays on the no-mail path.
 */
async function sendJoinConfirmation(env, email, { confirmToken, unsubToken, alreadyConfirmed, origin }) {
  const from = env.JOIN_FROM_EMAIL
  if (!from) {
    console.error('join: RESEND_API_KEY set but JOIN_FROM_EMAIL missing')
    return false
  }
  const confirmUrl = `${origin}/api/join/confirm?token=${confirmToken}`
  const unsubUrl = `${origin}/api/join/unsubscribe?token=${unsubToken}`
  const body = alreadyConfirmed
    ? [
        "You're already on the list on nathamuni.com — nothing further to do.",
        '',
        'Want off it? One click, no questions:',
        unsubUrl,
      ]
    : [
        'You asked to join the list on nathamuni.com.',
        '',
        'Confirm here (the link works for 7 days):',
        confirmUrl,
        '',
        "If this wasn't you, ignore this email — nothing will be sent, and the request",
        'expires on its own.',
        '',
        'Unsubscribe at any time:',
        unsubUrl,
      ]
  try {
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        authorization: `Bearer ${env.RESEND_API_KEY}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        from,
        to: email,
        subject: alreadyConfirmed ? "You're already on the list" : 'Confirm your spot',
        text: body.join('\n'),
        // Lets mail clients offer native one-click unsubscribe, and keeps senders in
        // good standing with Gmail/Yahoo bulk requirements.
        headers: {
          'List-Unsubscribe': `<${unsubUrl}>`,
          'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click',
        },
      }),
    })
    if (!res.ok) {
      console.error('join: resend responded', res.status)
      return false
    }
    return true
  } catch (err) {
    console.error('join: resend failed', err.message)
    return false
  }
}

/** Confirms or removes a subscription from an emailed link. */
async function handleJoinToken(request, env, action) {
  const token = new URL(request.url).searchParams.get('token') ?? ''
  const page = (msg, extra = '') =>
    new Response(
      `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">` +
        `<title>${msg}</title>` +
        `<body style="background:#0d0a1f;color:#f5f3ff;font:16px/1.6 system-ui,sans-serif;display:grid;place-items:center;min-height:100vh;margin:0;text-align:center;padding:2rem">` +
        `<main><p>${msg}</p>${extra}<p><a style="color:#b294ff" href="/">\u2190 nathamuni.com</a></p></main>`,
      {
        headers: {
          'content-type': 'text/html; charset=utf-8',
          // Bearer token sits in the URL: keep it out of referrers and shared caches.
          'referrer-policy': 'no-referrer',
          'cache-control': 'no-store',
        },
      }
    )

  const confirmButton = (label) =>
    `<form method="POST"><button style="margin:1rem 0;padding:.7rem 1.4rem;border-radius:9999px;border:1px solid #b294ff59;background:#8b5cf62e;color:#f5f3ff;font:inherit;cursor:pointer">${label}</button></form>`

  if (!env.INBOX || !token) return page('That link is not valid.')

  // GET is inert on purpose. Mail-security scanners follow every link in an email, so a
  // state-changing GET would let them confirm or unsubscribe people automatically.
  // RFC 8058 also requires one-click unsubscribe to be a POST.
  if (request.method === 'GET') {
    return action === 'unsubscribe'
      ? page('Unsubscribe from the list?', confirmButton('Yes, unsubscribe me'))
      : page('Confirm your subscription?', confirmButton('Yes, confirm'))
  }
  if (request.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 })
  }

  if (action === 'unsubscribe') {
    const email = await env.INBOX.get(`unsub:${token}`)
    if (!email) return page('That link is not valid.')
    const record = await env.INBOX.get(`join:${email}`, 'json')
    // Also drop any live confirmation token, or a pending confirm link from an older
    // email could resurrect the record after the person opted out.
    if (record?.confirmToken) await env.INBOX.delete(`jointoken:${record.confirmToken}`)
    await env.INBOX.delete(`join:${email}`)
    await env.INBOX.delete(`unsub:${token}`)
    return page('Unsubscribed. You will not hear from this list again.')
  }

  const email = await env.INBOX.get(`jointoken:${token}`)
  if (!email) return page('That link has expired or was already used.')
  const record = await env.INBOX.get(`join:${email}`, 'json')
  // Only a still-pending record may be confirmed. If it is gone the person unsubscribed
  // (or it expired), and confirming would silently re-add them.
  if (!record) return page('That link is no longer valid.')
  await env.INBOX.put(
    `join:${email}`,
    JSON.stringify({ ...record, status: 'confirmed', confirmedAt: new Date().toISOString(), confirmToken: undefined })
  )
  await env.INBOX.delete(`jointoken:${token}`)
  return page("You're in. Confirmed.")
}

async function handleJoin(request, env) {
  if (request.method !== 'POST') {
    return Response.json({ error: 'method not allowed' }, { status: 405 })
  }
  let body
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid request.' }, { status: 400 })
  }

  // Honeypot: bots fill every field — pretend success, store nothing.
  if ((body?.website ?? '').toString().trim() !== '') {
    return Response.json({ ok: true })
  }

  // Answered before the input is even looked at. A closed list is a property of the
  // site, not of what the visitor typed: complaining that their address is malformed
  // when nothing could be accepted either way is just misleading. Storage needs KV; a
  // confirmable signup additionally needs both mail secrets, because without them the
  // address could never be verified or unsubscribed.
  if (!env.INBOX || !env.RESEND_API_KEY || !env.JOIN_FROM_EMAIL) {
    return Response.json(
      { error: 'The lab list opens very soon — until then, DM me on Instagram.' },
      { status: 503 }
    )
  }

  const email = (body?.email ?? '').toString().trim().toLowerCase()
  const ambition = (body?.ambition ?? '').toString().trim().slice(0, JOIN_MAX_AMBITION_LEN)
  if (!EMAIL_RE.test(email) || email.length > 254) {
    return Response.json({ error: 'That email does not look right.' }, { status: 400 })
  }

  // Reuse the cache-counter mechanism: max 5 join attempts per IP per hour.
  const ip = request.headers.get('cf-connecting-ip') ?? 'unknown'
  const cache = caches.default
  const hourBucket = Math.floor(Date.now() / 3600_000)
  const joinKey = `https://rate.nathamuni.internal/join/${ip}/${hourBucket}`
  const prev = await readCounter(cache, joinKey)
  if (prev >= 5) {
    return Response.json({ error: 'Too many attempts — try again later.' }, { status: 429 })
  }
  await writeCounter(cache, joinKey, prev + 1, 3600)

  try {
    // Double opt-in: an address stays `pending` until the emailed link is followed, so
    // the list only ever contains people who proved they own the inbox. The guard that
    // the mail secrets exist at all is above, before anything is validated or stored.
    const token = crypto.randomUUID()
    const existing = await env.INBOX.get(`join:${email}`, 'json')
    const alreadyConfirmed = existing?.status === 'confirmed'
    // Stable across re-submits so previously sent newsletters keep unsubscribing.
    const unsubToken = existing?.unsubToken ?? crypto.randomUUID()

    const PENDING_TTL = 60 * 60 * 24 * 7 // 7 days — matches what the email promises

    await env.INBOX.put(
      `join:${email}`,
      JSON.stringify({
        email,
        ambition,
        at: new Date().toISOString(),
        status: alreadyConfirmed ? 'confirmed' : 'pending',
        unsubToken,
        confirmToken: alreadyConfirmed ? undefined : token,
      }),
      // An unconfirmed address disappears on its own, so an abandoned signup does not
      // leave someone's email sitting here forever — which is what the email says.
      alreadyConfirmed ? undefined : { expirationTtl: PENDING_TTL }
    )
    await env.INBOX.put(
      `unsub:${unsubToken}`,
      email,
      alreadyConfirmed ? undefined : { expirationTtl: PENDING_TTL }
    )
    if (!alreadyConfirmed) {
      await env.INBOX.put(`jointoken:${token}`, email, { expirationTtl: PENDING_TTL })
    }

    // Per-address cooldown on top of the per-IP limit. Without it a distributed
    // attacker rotating IPs could mail the same victim repeatedly, burning quota and
    // sender reputation. Silent: replying differently here would rebuild the
    // membership oracle the identical response shape exists to prevent.
    const mailKey = `https://rate.nathamuni.internal/joinmail/${encodeURIComponent(email)}`
    const mailedRecently = await readCounter(cache, mailKey)
    if (mailedRecently >= 1) {
      return Response.json({ ok: true, mailed: true })
    }
    await writeCounter(cache, mailKey, 1, 900) // one confirmation mail per address / 15 min

    const origin = new URL(request.url).origin
    // Mail goes out whether or not the address was already confirmed, and the response
    // is identical either way. Branching here would turn this endpoint into a
    // membership oracle: submit an address, read the reply, learn whether that person
    // is on the list.
    const sent = await sendJoinConfirmation(env, email, {
      confirmToken: token,
      unsubToken,
      alreadyConfirmed,
      origin,
    })
    // Same shape on mail failure, for the same reason.
    return Response.json({ ok: true, mailed: sent })
  } catch (err) {
    console.error('join error:', err.message)
    return Response.json({ error: 'Could not save that just now — try again.' }, { status: 500 })
  }
}

async function handleAsk(request, env) {
  if (request.method !== 'POST') {
    return Response.json({ error: 'method not allowed' }, { status: 405 })
  }

  let body
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid request.' }, { status: 400 })
  }

  const question = (body?.question ?? '').toString().trim()
  if (!question) {
    return Response.json({ error: 'Ask something first.' }, { status: 400 })
  }
  if (question.length > ASK_MAX_QUESTION_LEN) {
    return Response.json(
      { error: `Keep it under ${ASK_MAX_QUESTION_LEN} characters — short questions get better answers.` },
      { status: 400 }
    )
  }

  const rate = await checkAndBumpRateLimit(env, request)
  if (!rate.allowed) {
    const message =
      rate.reason === 'global'
        ? 'The twin is resting for today — the free daily quota ran out. Try again tomorrow, or ask the real one on Instagram.'
        : "That's enough questions for this hour — give the twin a breather and try again later."
    return Response.json({ error: message }, { status: 429 })
  }

  try {
    const [persona, { vectors, items }] = await Promise.all([getPersona(env, request), getIndex(env, request)])

    const [queryVector] = (await env.AI.run(MODEL, { text: [question] })).data
    const related = items
      .map((item, i) => ({ item, score: cosine(queryVector, vectors[i]) }))
      .sort((a, b) => b.score - a.score)
      .slice(0, ASK_TOP_K)
      .filter((r) => r.score > ASK_MIN_SCORE)
      .map((r) => r.item)

    // Single system message — some chat models reject multiple system turns.
    const messages = [
      { role: 'system', content: `${SYSTEM_PROMPT}\n\n${buildAskContext(persona, related)}` },
      { role: 'user', content: question },
    ]

    // Reasoning models can spend the whole token budget "thinking" on long or
    // unusual questions and return no visible text. Escalate through three
    // attempts: normal, then GLM's own /nothink switch which suppresses the
    // reasoning pass entirely, then a non-reasoning model that cannot fail
    // this way at all. A thrown attempt (model timeout, capacity) falls
    // through to the next rather than aborting the chain.
    let answer = ''
    let lastError = 'no attempt produced text'
    for (const attempt of [
      { model: ASK_MODEL, messages, max_tokens: ASK_MAX_TOKENS },
      {
        model: ASK_MODEL,
        messages: [
          messages[0],
          {
            role: 'user',
            content: `${question}\n\n/nothink\n(Answer directly in 2-5 sentences. Do not overthink.)`,
          },
        ],
        max_tokens: ASK_MAX_TOKENS + 800,
      },
      {
        model: ASK_FALLBACK_MODEL,
        messages: [
          messages[0],
          { role: 'user', content: `${question}\n\n(Answer directly in 2-5 sentences.)` },
        ],
        max_tokens: 600,
      },
    ]) {
      const { model, ...input } = attempt
      try {
        const result = await env.AI.run(model, input)
        answer = extractAnswer(result)
        if (answer) break
        lastError = `${model} returned no visible text: ${JSON.stringify(result).slice(0, 160)}`
      } catch (err) {
        lastError = `${model} threw: ${err.message}`
      }
      console.warn('ask attempt failed:', lastError)
    }
    if (!answer) throw new Error(lastError)

    await logQuestion(env, question, 'answered')
    return Response.json({ answer })
  } catch (err) {
    console.error('ask error:', err.message)
    await logQuestion(env, question, 'failed')
    return Response.json(
      { error: "The twin's brain hiccuped mid-thought — try asking again in a moment." },
      { status: 200 }
    )
  }
}

/**
 * Workers AI text models differ in response shape, and reasoning models may
 * wrap visible output around <think> blocks — normalize all of it to a string.
 */
function extractAnswer(result) {
  if (!result) return ''
  let text = ''
  if (typeof result === 'string') text = result
  else {
    const cand =
      result.response ??
      result.result?.response ??
      result.output_text ??
      result.choices?.[0]?.message?.content ??
      ''
    text = typeof cand === 'string' ? cand : ''
  }
  return text
    .replace(/<think>[\s\S]*?<\/think>/g, '')
    .replace(/^[\s\S]*?<\/think>/, (m) => (m.length < text.length ? '' : m))
    .trim()
}

async function handleVideos(request, env) {
  try {
    const videosRes = await env.ASSETS.fetch(new URL('/videos.json', request.url))
    if (!videosRes.ok) {
      return Response.json({ error: 'videos data not found' }, { status: 404 })
    }
    const videos = await videosRes.json()
    return Response.json(videos, { headers: { 'cache-control': 'public, max-age=300' } })
  } catch (err) {
    console.error('videos error:', err.message)
    return Response.json({ error: 'videos unavailable' }, { status: 500 })
  }
}

async function handleSearch(request, env) {
  const q = new URL(request.url).searchParams.get('q')?.trim() ?? ''
  if (q.length < 3 || q.length > 200) {
    return Response.json({ results: [] })
  }
  const { vectors, items } = await getIndex(env, request)
  const [queryVector] = (await env.AI.run(MODEL, { text: [q] })).data

  const scored = items
    .map((item, i) => ({ id: item.id, score: cosine(queryVector, vectors[i]) }))
    .sort((a, b) => b.score - a.score)
    .slice(0, TOP_K)
    .filter((r) => r.score > 0.4)

  return Response.json(
    { results: scored },
    { headers: { 'cache-control': 'public, max-age=3600' } }
  )
}

const worker = {
  async fetch(request, env) {
    const { pathname } = new URL(request.url)
    if (pathname === '/api/videos') {
      return handleVideos(request, env)
    }
    if (pathname === '/api/search') {
      try {
        return await handleSearch(request, env)
      } catch (err) {
        console.error('search error:', err.message)
        return Response.json({ results: [], error: 'search unavailable' }, { status: 200 })
      }
    }
    if (pathname === '/api/ask') {
      return handleAsk(request, env)
    }
    if (pathname === '/api/join') {
      try {
        return await handleJoin(request, env)
      } catch (err) {
        console.error('join fatal:', err.message)
        return Response.json({ error: 'Could not save that just now — try again.' }, { status: 500 })
      }
    }
    // Followed from a confirmation email, so these are GET links, not API calls.
    if (pathname === '/api/join/confirm' || pathname === '/api/join/unsubscribe') {
      try {
        return await handleJoinToken(request, env, pathname.endsWith('unsubscribe') ? 'unsubscribe' : 'confirm')
      } catch (err) {
        console.error('join token fatal:', err.message)
        return new Response('Something went wrong.', { status: 500 })
      }
    }
    if (pathname.startsWith('/api/auth/')) {
      try {
        return await handleAuth(request, env, pathname.slice('/api/auth/'.length))
      } catch (err) {
        console.error('auth fatal:', err.message)
        return Response.json({ error: 'Something went wrong — try again.' }, { status: 500 })
      }
    }
    return env.ASSETS.fetch(request)
  },
}

export default worker
